import React, { createContext, useContext, useId, useState } from 'react';
import { getRadioState, radioGroupStyleKeys } from '../lib/core';
import type { RadioGroupBaseProps, RadioGroupItemBaseProps } from '../lib/core';
import styles from './radio-group.module.scss';

interface RadioGroupContextValue {
	value: string;
	name: string;
	disabled: boolean;
	select: (value: string) => void;
}

const RadioGroupContext = createContext<RadioGroupContextValue | null>(null);

function useRadioGroupContext(): RadioGroupContextValue {
	const context = useContext(RadioGroupContext);
	if (!context) {
		throw new Error('RadioGroup sub-components must be used within <RadioGroup>.');
	}
	return context;
}

export interface RadioGroupProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'value' | 'defaultValue'>, RadioGroupBaseProps {}

const RadioGroup = React.forwardRef<HTMLDivElement, RadioGroupProps>(
	({ className = '', value, defaultValue = '', onValueChange, orientation = 'vertical', name = '', disabled = false, children, ...props }, ref) => {
		const [internalValue, setInternalValue] = useState(defaultValue);
		const currentValue = value !== undefined ? value : internalValue;

		function select(next: string) {
			if (disabled) {
				return;
			}
			if (value === undefined) {
				setInternalValue(next);
			}
			onValueChange?.(next);
		}

		return (
			<RadioGroupContext.Provider value={{ value: currentValue, name, disabled, select }}>
				<div
					ref={ref}
					role="radiogroup"
					aria-orientation={orientation}
					data-orientation={orientation}
					className={`${styles[radioGroupStyleKeys.root]} ${className}`}
					{...props}>
					{children}
				</div>
			</RadioGroupContext.Provider>
		);
	},
);
RadioGroup.displayName = 'RadioGroup';

export interface RadioGroupItemProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'value' | 'checked'>, RadioGroupItemBaseProps {
	value: string;
}

const RadioGroupItem = React.forwardRef<HTMLInputElement, RadioGroupItemProps>(({ className = '', value, disabled = false, onChange, children, ...props }, ref) => {
	const context = useRadioGroupContext();
	const checked = context.value === value;
	const state = getRadioState(checked);
	const inputId = useId();

	function handleChange(event: React.ChangeEvent<HTMLInputElement>) {
		context.select(value);
		onChange?.(event);
	}

	return (
		<label htmlFor={inputId} className={`${styles[radioGroupStyleKeys.label]} ${className}`}>
			<input
				{...props}
				ref={ref}
				id={inputId}
				type="radio"
				name={context.name}
				value={value}
				checked={checked}
				disabled={disabled || context.disabled}
				onChange={handleChange}
				className={styles[radioGroupStyleKeys.input]}
			/>
			<span aria-hidden data-state={state} className={styles[radioGroupStyleKeys.item]}>
				<span className={styles[radioGroupStyleKeys.indicator]}>
					<span className={styles[radioGroupStyleKeys.dot]} />
				</span>
			</span>
			{children}
		</label>
	);
});
RadioGroupItem.displayName = 'RadioGroupItem';

export { RadioGroup, RadioGroupItem };
export default RadioGroup;

@use '../../../styles/variables/colors' as *;

.root {
	display: grid;
	gap: $spacing-3;

	&[data-orientation='horizontal'] {
		grid-auto-flow: column;
		grid-auto-columns: max-content;
	}
}

.label {
	position: relative;
	display: inline-flex;
	flex-shrink: 0;
	cursor: pointer;
}

.input {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 100%;
	margin: 0;
	opacity: 0;
	cursor: pointer;

	&:focus-visible + .item {
		border-color: var(--tile-radio-focus-border, #{$ring});
		box-shadow: var(--tile-radio-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
		outline: var(--tile-radio-focus-outline, none);
		outline-offset: var(--tile-radio-focus-offset, 0px);
	}

	&:disabled {
		cursor: not-allowed;
	}

	&:disabled + .item {
		cursor: not-allowed;
		opacity: 0.5;
	}
}

.item {
	display: inline-flex;
	width: 1rem;
	height: 1rem;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	border: var(--tile-radio-border-width, 1px) solid var(--tile-radio-border, #{$input});
	border-radius: $radius-full;
	background-color: var(--tile-radio-background, #{$background});
	color: var(--tile-radio-color, #{$primary});
	box-shadow: var(--tile-radio-shadow, none);
	transition:
		border-color $transition-fast,
		box-shadow $transition-fast,
		color $transition-fast;
	outline: none;

	&[data-state='checked'] {
		border-color: var(--tile-radio-checked-border, #{$primary});
		background-color: var(--tile-radio-checked-background, #{$background});
		color: var(--tile-radio-checked-color, #{$primary});
		box-shadow: var(--tile-radio-checked-shadow, none);
	}
}

.input:focus-visible + .item[data-state='checked'] {
	box-shadow: var(--tile-radio-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
}

.indicator {
	display: flex;
	width: 100%;
	height: 100%;
	align-items: center;
	justify-content: center;
}

.dot {
	width: 0.5rem;
	height: 0.5rem;
	border-radius: $radius-full;
	background-color: currentColor;
}
